css:
@keyframes blink {
  50% {
    opacity: 0;
  }
}

@keyframes reveal {
  0%, 60% {
    background: var(--color-accent-soft);
    box-shadow: 0 0 0 0.75rem var(--color-accent-soft);
  }

  to {
    background: transparent;
    box-shadow: 0 0 0 0.75rem transparent;
  }
}

@keyframes marker-sweep {
  to {
    background-size: 100% 100%;
  }
}

@keyframes marker-fade {
  from {
    opacity: 0;
  }
}

@keyframes page-out {
  to {
    opacity: 0;
  }
}

@keyframes page-in-forward {
  from {
    opacity: 0;
    translate: -1.5rem 0;
  }
}

@keyframes page-in-back {
  from {
    opacity: 0;
    translate: 1.5rem 0;
  }
}

@keyframes page-in-from-right {
  from {
    opacity: 0;
    translate: 1.5rem 0;
  }
}

@keyframes page-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes cover-content-in {
  0%, 30% {
    opacity: 0;
  }
}

::view-transition-group(root) {
  animation-duration: 180ms;
  animation-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

::view-transition-group(reader-page) {
  animation-duration: 200ms;
  animation-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

::view-transition-old(reader-page) {
  animation-name: page-out;
  animation-duration: 90ms;
  animation-fill-mode: both;
}

:active-view-transition-type(forward)::view-transition-new(reader-page) {
  animation-name: page-in-forward;
  animation-delay: 40ms;
  animation-fill-mode: both;
}

:active-view-transition-type(back)::view-transition-new(reader-page) {
  animation-name: page-in-back;
  animation-delay: 40ms;
  animation-fill-mode: both;
}

::view-transition-group(page-counter) {
  animation-duration: 0s;
}

::view-transition-old(page-counter) {
  display: none;
}

::view-transition-new(page-counter) {
  animation: none;
}

::view-transition-group(book-cover) {
  animation-duration: 420ms;
  animation-timing-function: cubic-bezier(0.32, 0.72, 0, 1);
}

::view-transition-new(book-cover) {
  animation-name: cover-content-in;
  animation-duration: 420ms;
}

::view-transition-group(book-cover.closing) {
  animation-duration: 360ms;
}
/* Opening: the old cover fades quickly so it never looks stretched as it grows. */

::view-transition-old(book-cover) {
  animation-name: page-out;
  animation-duration: 160ms;
  animation-timing-function: ease-out;
  animation-fill-mode: both;
}

::view-transition-old(book-cover.closing) {
  animation-name: page-out;
  animation-duration: 160ms;
  animation-timing-function: ease-out;
  animation-fill-mode: both;
}

::view-transition-new(book-cover.closing) {
  animation-duration: 360ms;
}

::view-transition-old(page-scrubber.closing) {
  animation-name: page-out;
  animation-duration: 120ms;
  animation-timing-function: ease-out;
  animation-fill-mode: both;
}

::view-transition-old(page-counter.closing) {
  display: block;
  animation-name: page-out;
  animation-duration: 120ms;
  animation-timing-function: ease-out;
  animation-fill-mode: both;
}

@media (prefers-reduced-motion: reduce) {
  :active-view-transition-type(forward)::view-transition-new(reader-page) {
    animation-name: page-fade-in;
  }

  :active-view-transition-type(back)::view-transition-new(reader-page) {
    animation-name: page-fade-in;
  }

  ::view-transition-group(book-cover) {
    animation-duration: 0s;
  }

  ::view-transition-group(book-cover.closing) {
    animation-duration: 0s;
  }
}

@property --fade-top {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@property --fade-bottom {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@keyframes gloss-fade {
  from {
    --fade-top: 0px;
    --fade-bottom: 1.5rem;
  }

  to {
    --fade-top: 1.5rem;
    --fade-bottom: 0px;
  }
}

@keyframes footnote-reveal {
  0%, 60% {
    background-color: var(--color-accent-soft);
  }

  100% {
    background-color: transparent;
  }
}

@keyframes screen-in-forward {
  from {
    opacity: 0;
    translate: 1.5rem 0;
  }
}

@keyframes screen-in-back {
  from {
    opacity: 0;
    translate: -1.5rem 0;
  }
}

@keyframes screen-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes bookmark-pop {
  0% {
    scale: 1;
  }

  40% {
    scale: 1.2;
  }

  100% {
    scale: 1;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes copied-flash {
  from {
    opacity: 0;
    translate: -50% 3px;
  }
}

@keyframes copied-fade {
  from {
    opacity: 0;
  }
}

@keyframes answer-stream {
  from {
    clip-path: inset(0 0 100% 0);
  }

  to {
    clip-path: inset(0);
  }
}

@keyframes page-note-settle {
  from {
    scale: 0.98;
    background-color: color-mix(in oklab, var(--color-accent) 22%, transparent);
  }
}

@keyframes page-note-wash {
  from {
    background-color: color-mix(in oklab, var(--color-accent) 22%, transparent);
  }
}

@keyframes pin-set {
  from {
    rotate: -45deg;
    scale: 0.6;
  }
}

::view-transition-group(*.book-card) {
  animation-duration: 280ms;
  animation-timing-function: cubic-bezier(0.645, 0.045, 0.355, 1);
}

