  transition:
    fill {transition.duration-press} {ease.out},
    scale {transition.duration-pop} {ease.out};
}

&[data-state="bookmarked"] svg {
  fill: currentColor;
  animation: bookmark-pop {transition.duration-sweep} {ease.out};
}

@media (prefers-reduced-motion: reduce) {
  &[data-state="bookmarked"] svg {
    animation: none;
  }
}

xvsNSMYl.css:
